import { Composio } from '@composio/core';

async function main() {
    const composio = new Composio({ apiKey: "test" });

    // We want to use `composio.create()`
    // Let's create a session with config
    const session = await composio.create('zealt-user01', {
        authConfigs: {
            github: {
                scopes: ['repo', 'read:org', 'user']
            }
        }
    });

    console.log(session);
}

